// Included in the isolated TracyWorker.cpp generated by prepare.py.
#include <functional>
#include <stdexcept>
#include <unordered_map>

namespace tracy {
namespace crop {
template<class T, class Predicate>
void Filter(Vector<T>& input, Predicate keep) {
    Vector<T> output;
    for (const auto& item : input) if (keep(item)) output.push_back(item);
    input = std::move(output);
}
template<class T, class Compare, class Predicate>
void Filter(SortedVector<T, Compare>& input, Predicate keep) {
    input.ensure_sorted();
    SortedVector<T, Compare> output;
    for (const auto& item : input) if (keep(item)) output.push_back(item);
    input = std::move(output);
}
// Serialized files use contiguous ("magic") ZoneEvent vectors. Preserve their
// representation: a normal vector of short_ptr is a different storage layout.
template<class Predicate, class Visit, class SlabType>
void Zones(Vector<short_ptr<ZoneEvent>>& input, Predicate keep, Visit visit, SlabType& slab) {
    if (input.is_magic()) {
        auto& direct = reinterpret_cast<Vector<ZoneEvent>&>(input);
        Vector<ZoneEvent> output;
        uint32_t size = 0;
        for (const auto& z : direct) if (keep(z)) ++size;
        if (size) output.reserve_exact(size, slab);
        uint32_t index = 0;
        for (const auto& z : direct) if (keep(z)) {
            auto copy = z;
            visit(copy);
            output[index++] = copy;
        }
        direct = std::move(output);
        direct.set_magic();
    } else {
        Vector<short_ptr<ZoneEvent>> output;
        for (auto p : input) if (keep(*p)) { visit(*p); output.push_back(p); }
        input = std::move(output);
    }
}
}

void Worker::Crop(int64_t begin, int64_t end) {
    DoPostponedWorkAll();
    if (begin < 0 || end <= begin || begin >= m_data.lastTime)
        throw std::runtime_error("Range is empty, invalid, or starts beyond this trace");
    // GPU timestamps have independent calibration/overflow semantics. Fail
    // explicitly instead of silently writing a partly cropped GPU capture.
    if (m_data.gpuCnt != 0)
        throw std::runtime_error("GPU zones are not supported by this CPU trace cropper");
    const int64_t originalEnd = m_data.lastTime;
    end = std::min(end, originalEnd);
    auto overlaps = [&](int64_t a, int64_t b) {
        return a <= end && (b < 0 ? originalEnd : b) >= begin;
    };
    auto point = [&](int64_t t) { return t >= begin && t <= end; };
    int64_t earliest = begin, latest = end;
    auto include = [&](int64_t a, int64_t b) {
        earliest = std::min(earliest, a);
        latest = std::max(latest, b < 0 ? originalEnd : b);
    };

    Vector<Vector<short_ptr<ZoneEvent>>> children;
    Vector<ZoneExtra> extras;
    extras.push_back(m_data.zoneExtra[0]); // index zero is Tracy's sentinel
    std::unordered_map<uint32_t, uint32_t> extraMap;
    m_data.sourceLocationZonesCnt.clear();
    m_data.zonesCnt = 0;
    std::function<uint64_t(Vector<short_ptr<ZoneEvent>>&)> prune;
    prune = [&](auto& timeline) {
        uint64_t count = 0;
        crop::Zones(timeline, [&](const auto& z) { return overlaps(z.Start(), z.End()); },
            [&](ZoneEvent& z) {
                ++count;
                ++m_data.sourceLocationZonesCnt[z.SrcLoc()];
                include(z.Start(), z.End());
                if (z.extra) {
                    auto [it, added] = extraMap.emplace(z.extra, uint32_t(extras.size()));
                    if (added) extras.push_back(m_data.zoneExtra[z.extra]);
                    z.extra = it->second;
                }
                if (z.HasChildren()) {
                    auto& old = m_data.zoneChildren[z.Child()];
                    count += prune(old);
                    if (old.empty()) z.SetChild(-1);
                    else {
                        z.SetChild(int32_t(children.size()));
                        children.push_back(std::move(old));
                    }
                }
            }, m_slab);
        return count;
    };
    m_data.samplesCnt = 0;
    for (auto td : m_data.threads) {
        td->count = prune(td->timeline);
        m_data.zonesCnt += td->count;
        crop::Filter(td->messages, [&](auto m) { return point(m->time); });
        crop::Filter(td->samples, [&](const auto& s) { return point(s.time.Val()); });
        crop::Filter(td->ctxSwitchSamples, [&](const auto& s) { return point(s.time.Val()); });
        td->kernelSampleCnt = 0;
        for (const auto& s : td->samples) if (GetCanonicalPointer(GetCallstack(s.callstack.Val())[0]) >> 63) ++td->kernelSampleCnt;
        m_data.samplesCnt += td->samples.size();
    }
    // Release removed child vectors before replacing the child table.
    for (auto& old : m_data.zoneChildren) old.~Vector();
    m_data.zoneChildren = std::move(children);
    m_data.zoneExtra = std::move(extras);
    crop::Filter(m_data.messages, [&](auto m) { return point(m->time); });

    for (auto plot : m_data.plots.Data()) {
        if (plot->type == PlotType::Memory) continue; // rebuilt from allocations on load
        plot->data.ensure_sorted();
        // One sample on either side preserves interpolation/step context.
        int64_t before = -1, after = -1;
        for (const auto& p : plot->data) {
            auto t = p.time.Val();
            if (t < begin) before = t;
            if (t > end) { after = t; break; }
        }
        crop::Filter(plot->data, [&](const auto& p) {
            auto t = p.time.Val();
            return point(t) || t == before || t == after;
        });
        plot->min = plot->data.empty() ? 0 : std::numeric_limits<double>::max();
        plot->max = plot->data.empty() ? 0 : std::numeric_limits<double>::lowest();
        plot->sum = 0;
        for (const auto& p : plot->data) {
            include(p.time.Val(), p.time.Val());
            plot->min = std::min(plot->min, p.val);
            plot->max = std::max(plot->max, p.val);
            plot->sum += p.val;
        }
    }
    for (auto fd : m_data.frames.Data()) {
        Vector<FrameEvent> frames;
        // Preserve original frame intervals. Continuous frames become explicit
        // intervals so the next boundary isn't accidentally turned into a frame.
        for (size_t i = 0; i < fd->frames.size(); ++i) {
            auto f = fd->frames[i];
            auto finish = fd->continuous ? (i + 1 < fd->frames.size() ? fd->frames[i+1].start : originalEnd) : f.end;
            if (overlaps(f.start, finish)) {
                f.end = finish;
                include(f.start, finish);
                frames.push_back(f);
            }
        }
        fd->continuous = 0;
        fd->frames = std::move(frames);
    }
    // Tracy's frame UI assumes each retained frameset is nonempty.
    if (m_data.framesBase->frames.empty()) m_data.framesBase->frames.push_back({begin, end, -1});
    crop::Filter(m_data.frames.Data(), [&](FrameData* fd) {
        if (fd == m_data.framesBase || !fd->frames.empty()) return true;
        fd->~FrameData();
        return false;
    });
    Vector<short_ptr<FrameImage>> images;
    std::unordered_map<int32_t, int32_t> imageMap;
    for (auto fd : m_data.frames.Data()) for (auto& frame : fd->frames) if (frame.frameImage >= 0) {
        auto [it, added] = imageMap.emplace(frame.frameImage, int32_t(images.size()));
        if (added) images.push_back(m_data.frameImage[frame.frameImage]);
        frame.frameImage = it->second;
    }
    m_data.frameImage = std::move(images);
    // GetFirstTime() assumes three special frames in on-demand files. Cropped
    // files keep the original absolute time axis and no longer use that mode.
    m_onDemand = false;
    m_data.frameOffset = 0;
    for (auto& section : m_data.sections) {
        crop::Filter(section.second, [&](const auto& s) { return overlaps(s.start.Val(), s.end.Val()); });
        for (const auto& s : section.second) include(s.start.Val(), s.end.Val());
    }
    // Lock events encode dependent state transitions. Conservatively keep the
    // complete history of an overlapping lock, including later releases.
    for (auto it = m_data.lockMap.begin(); it != m_data.lockMap.end();) {
        auto lock = it->second;
        if (!overlaps(lock->timeAnnounce, lock->timeTerminate == 0 ? -1 : lock->timeTerminate)) {
            lock->~LockMap();
            it = m_data.lockMap.erase(it);
        } else {
            include(lock->timeAnnounce, lock->timeAnnounce);
            if (lock->timeTerminate > 0) include(lock->timeTerminate, lock->timeTerminate);
            for (const auto& e : lock->timeline) include(e.ptr->Time(), e.ptr->Time());
            ++it;
        }
    }
    for (auto& memory : m_data.memNameMap) {
        auto& m = *memory.second;
        crop::Filter(m.data, [&](const auto& a) { return overlaps(a.TimeAlloc(), a.TimeFree()); });
        m.active.clear();
        m.frees = Vector<uint32_t>();
        m.high = 0;
        m.low = std::numeric_limits<uint64_t>::max();
        m.usage = 0;
        for (uint32_t i = 0; i < m.data.size(); ++i) {
            const auto& a = m.data[i];
            include(a.TimeAlloc(), a.TimeFree());
            m.low = std::min(m.low, a.Ptr());
            m.high = std::max(m.high, a.Ptr() + a.Size());
            if (a.TimeFree() < 0) { m.active.emplace(a.Ptr(), i); m.usage += a.Size(); }
            else m.frees.push_back(i);
        }
        if (m.data.empty()) m.low = 0;
        if (!m.frees.empty()) std::sort(m.frees.begin(), m.frees.end(), [&](auto a, auto b) { return m.data[a].TimeFree() < m.data[b].TimeFree(); });
    }
    m_data.cpuThreadData.clear();
    for (auto& ctx : m_data.ctxSwitch) {
        auto& c = *ctx.second;
        crop::Filter(c.v, [&](const auto& e) { return overlaps(e.Start(), e.End()); });
        c.runningTime = 0;
        int previousCpu = -1;
        for (const auto& e : c.v) {
            include(std::min(e.Start(), e.WakeupVal()), e.End());
            if (e.End() >= 0) c.runningTime += e.End() - e.Start();
            if (previousCpu >= 0 && previousCpu != e.Cpu()) ++m_data.cpuThreadData[ctx.first].migrations;
            previousCpu = e.Cpu();
        }
    }
    for (auto& cpu : m_data.cpuData) {
        crop::Filter(cpu.cs, [&](const auto& e) { return overlaps(e.Start(), e.End()); });
        for (const auto& e : cpu.cs) {
            include(e.Start(), e.End());
            auto& summary = m_data.cpuThreadData[DecompressThreadExternal(e.Thread())];
            if (e.End() >= 0) summary.runningTime += e.End() - e.Start();
            ++summary.runningRegions;
        }
    }
    for (auto& hw : m_data.hwSamples) {
        auto filter = [&](auto& v) { crop::Filter(v, [&](const auto& t) { return point(t.Val()); }); };
        filter(hw.second.cycles); filter(hw.second.retired);
        filter(hw.second.cacheRef); filter(hw.second.cacheMiss);
        filter(hw.second.branchRetired); filter(hw.second.branchMiss);
    }
    if (m_data.crashEvent.thread && !point(m_data.crashEvent.time)) m_data.crashEvent = {};
    m_data.lastTime = latest;
    std::fprintf(stderr, "Retained event/frame extent: %.9f .. %.9f seconds (original time axis).\n", earliest / 1e9, latest / 1e9);
}

}
